select 'flag' as k, nombre as a, activo::text as b, coalesce(descripcion,'') as c from crm.multiempresa_flags union all select 'schema_usage', nspname, has_schema_privilege('authenticated', nspname, 'USAGE')::text, has_schema_privilege('anon', nspname, 'USAGE')::text from pg_namespace where nspname in ('crm','private','public') union all select 'db_version', version(), '', '' union all select 'now', now()::text, '', '' order by 1,2
